// Klaus — finance: deterministic invoice math. NO LLM does the numbers.
// German conventions: Rechnungsnummer, net-14 default, USt/VAT 19% default,
// §19 Kleinunternehmer option (omits VAT row).

const src = $json.body && Object.keys($json.body).length ? $json.body : $json;

// ---- de-EUR number formatting (1.234,56) ----
const eur = (n) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// ---- inputs (with safe demo defaults so the GET webhook works for testing) ----
const clientName = src.clientName || 'Beispiel GmbH';
const invoiceNo  = src.invoiceNo  || 'DRAFT-0001';
const dueDate    = src.dueDate    || null;

let lineItems = src.lineItems;
if (typeof lineItems === 'string') { try { lineItems = JSON.parse(lineItems); } catch (e) { lineItems = null; } }
if (!Array.isArray(lineItems) || lineItems.length === 0) {
  lineItems = [
    { desc: 'Web development (Sprint 1)', qty: 1, unitPrice: 2400 },
    { desc: 'UX consulting',               qty: 6, unitPrice: 120 }
  ];
}

// ---- tax config ----
const kleinunternehmer = src.kleinunternehmer === true || src.kleinunternehmer === 'true';
const vatRate = kleinunternehmer ? 0 : (src.vatRate != null ? Number(src.vatRate) : 19);

// ---- dates (Europe/Berlin), net-14 default ----
const today = new Date();
const fmtDate = (d) => d.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Europe/Berlin' });
const issueDate = fmtDate(today);
let dueStr;
if (dueDate) { const d = new Date(dueDate); dueStr = isNaN(d) ? String(dueDate) : fmtDate(d); }
else { const d = new Date(today.getTime()); d.setDate(d.getDate() + 14); dueStr = fmtDate(d); }

// ---- math (round per line, then sum) ----
let subtotal = 0;
const rows = lineItems.map((it) => {
  const qty = Number(it.qty) || 0;
  const unit = Number(it.unitPrice) || 0;
  const amount = Math.round(qty * unit * 100) / 100;
  subtotal += amount;
  return { desc: String(it.desc || ''), qty, unit, amount };
});
subtotal = Math.round(subtotal * 100) / 100;
const vatAmount = Math.round(subtotal * (vatRate / 100) * 100) / 100;
const total = Math.round((subtotal + vatAmount) * 100) / 100;

return [{ json: {
  clientName,
  invoiceNo,
  issueDate,
  dueStr,
  paymentTerms: 'Zahlbar innerhalb von 14 Tagen netto',
  kleinunternehmer,
  vatRate,
  rows,
  subtotal,
  vatAmount,
  total,
  subtotal_fmt: eur(subtotal),
  vatAmount_fmt: eur(vatAmount),
  total_fmt: eur(total)
} }];

// Fill templates/invoice.html (embedded — n8n container cannot read the host FS).
// German invoicing conventions per the client-invoice skill reference.
const d = $json;
const eur = (n) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

// ---- agency constants (placeholders until a real source/Postgres exists) ----
const AGENCY_NAME    = 'Rachek Software';
const AGENCY_ADDRESS = 'Musterstraße 1, 10115 Berlin';
const AGENCY_VAT_ID  = 'DE000000000';
const AGENCY_EMAIL   = 'achrafrachek1@gmail.com';
const IBAN = 'DE00 0000 0000 0000 0000 00';
const BIC  = 'XXXXDEXX';
const LOGO_B64 = '';

// ---- line-item rows ----
const rowsHtml = (d.rows || []).map(r =>
  `<tr><td>${esc(r.desc)}</td><td class="right">${r.qty}</td><td class="right">${eur(r.unit)}</td><td class="right">${eur(r.amount)}</td></tr>`
).join('');

// ---- VAT row + legal footer: §19 Kleinunternehmer omits VAT ----
const vatRowHtml = d.kleinunternehmer
  ? ''
  : `<tr><td>USt (${d.vatRate}%)</td><td class="right">€${eur(d.vatAmount)}</td></tr>`;
const legalFooter = d.kleinunternehmer
  ? `${AGENCY_NAME} · ${AGENCY_ADDRESS} · ${AGENCY_VAT_ID}. Gemäß § 19 UStG wird keine Umsatzsteuer berechnet.`
  : `${AGENCY_NAME} · ${AGENCY_ADDRESS} · USt-IdNr ${AGENCY_VAT_ID}. ${d.paymentTerms}.`;
const notes = 'Vielen Dank für Ihren Auftrag.';

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  :root{
    --brand:#1F3A5F; --accent:#3E7CB1; --ink:#1A1A1A; --muted:#6B7280;
    --line:#E5E7EB; --bg-soft:#F7F9FC; --font:'Helvetica Neue',Arial,sans-serif;
  }
  @page{ size:A4; margin:18mm 16mm; }
  *{ box-sizing:border-box; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  body{ font-family:var(--font); color:var(--ink); font-size:11pt; line-height:1.5; margin:0; }
  h1{ color:var(--brand); font-size:22pt; margin:0 0 4px; }
  h2{ color:var(--brand); font-size:13pt; border-bottom:2px solid var(--accent);
      padding-bottom:4px; margin:24px 0 10px; }
  .muted{ color:var(--muted); } .right{ text-align:right; } .small{ font-size:9pt; }
  .brandbar{ height:6px; background:linear-gradient(90deg,var(--brand),var(--accent)); }
  table{ width:100%; border-collapse:collapse; margin:8px 0; }
  th{ background:var(--brand); color:#fff; text-align:left; padding:8px 10px; font-size:9.5pt;
      text-transform:uppercase; letter-spacing:.04em; }
  td{ padding:8px 10px; border-bottom:1px solid var(--line); vertical-align:top; }
  tr:nth-child(even) td{ background:var(--bg-soft); }
  .totals td{ border:none; padding:4px 10px; }
  .totals .grand{ font-size:13pt; font-weight:700; color:var(--brand);
      border-top:2px solid var(--brand); }
  .badge{ display:inline-block; background:var(--bg-soft); border:1px solid var(--line);
      border-radius:6px; padding:2px 8px; font-size:9pt; color:var(--muted); }
  .header-flex{ display:flex; justify-content:space-between; align-items:flex-start; }
  .logo{ height:40px; }
</style>
</head>
<body>
<div class="brandbar"></div>
<div class="header-flex" style="margin-top:20px">
  <div>
    <h1>Rechnung</h1>
    <div class="muted small">${esc(AGENCY_NAME)} · ${esc(AGENCY_ADDRESS)}<br>
      USt-IdNr: ${esc(AGENCY_VAT_ID)} · ${esc(AGENCY_EMAIL)}</div>
  </div>
  <div class="right small">
    <div class="badge">Rechnungsnr. ${esc(d.invoiceNo)}</div><br><br>
    <strong>Datum:</strong> ${esc(d.issueDate)}<br>
    <strong>Fällig:</strong> ${esc(d.dueStr)}
  </div>
</div>
<h2>Rechnung an</h2>
<div>${esc(d.clientName)}</div>
<h2>Leistungen</h2>
<table>
  <thead>
    <tr><th>Beschreibung</th><th class="right">Menge</th>
        <th class="right">Einzel (€)</th><th class="right">Betrag (€)</th></tr>
  </thead>
  <tbody>${rowsHtml}</tbody>
</table>
<table class="totals" style="width:45%;margin-left:auto">
  <tr><td>Zwischensumme</td><td class="right">€${eur(d.subtotal)}</td></tr>
  ${vatRowHtml}
  <tr><td class="grand">Gesamtbetrag</td><td class="right grand">€${eur(d.total)}</td></tr>
</table>
<h2>Zahlung</h2>
<div class="small">IBAN ${esc(IBAN)} · BIC ${esc(BIC)} · Verwendungszweck: ${esc(d.invoiceNo)}<br>${esc(d.paymentTerms)}.<br>${esc(notes)}</div>
<div class="small muted" style="margin-top:24px">${esc(legalFooter)}</div>
</body>
</html>`;

return [{ json: { html, invoiceNo: d.invoiceNo, clientName: d.clientName, total_fmt: d.total_fmt } }];
